if ('serviceWorker' in navigator) {
            window.addEventListener('load', () => {
                navigator.serviceWorker.register('./sw.js').then(reg => {
                    reg.update();
                });
            });
            if ('caches' in window) {
                caches.keys().then(names => {
                    for (let name of names) {
                        if (name !== 'qr-rover-v17') {
                            caches.delete(name);
                        }
                    }
                });
            }
        }
